@settings {
  template: systems;
  element-size: 47;
  font-size: 42;
  element-text-overflow: auto;
  connection-size: 4;
  element-color: #c6c6c6;
  element-text-align: center;
  font-color: #000000;
  opposite-style: none;
  connection-color: #868686;
}

connection["tags"="hypothesized"] {
  style: dashed;
}

/* wider arrows = downscale connections */
connection["tags"="downscale"] {
  size: 15;
  connection-color: #686868;
}

/* elements: larger circles = key subsystem variables */
["Tags"~="key"] {
  size: 72;
}

element["element type"="network"] {
  color: #fff0a5;
}

element["element type"="impact"] {
  color: #f53b23;
}

element["element type"="social"] {
    color: #82bbdb;
}

element["element type"="experiential"] {
  color: #74c89e;
}

element["element type"="neurometabolic cascade"] {
  color: #fd9e43;
}

element["element type"="neuroinflammation"] {
  color: #fdc16f;
}

element["element type"="sensorimotor / predictive brain state"] {
  color: #87ce85;
}

element["element type"="stress / mood"] {
  color: #5abc67;
}

element["element type"="sleep/fatigue"] {
  color: #aedfa7;
}

element["element type"="cellular energy imbalance"] {
  color: #fdd5ac;
}

element["element type"="axonal injury"] {
  color: #fede7f;
}

